package com.finsight.domain; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class AuditEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long applicationId; String eventType,description,actor; LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public Long getApplicationId(){return applicationId;} public String getEventType(){return eventType;} public String getDescription(){return description;} public String getActor(){return actor;} public LocalDateTime getCreatedAt(){return createdAt;} public void setApplicationId(Long v){applicationId=v;} public void setEventType(String v){eventType=v;} public void setDescription(String v){description=v;} public void setActor(String v){actor=v;} }
